using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;using D=System.Drawing;
class Process527Tests {
 static int checks,failures;static void Check(bool v,string n){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var v in Tree(VisualTreeHelper.GetChild(o,i)))yield return v;}static T Named<T>(DependencyObject w,string n)where T:DependencyObject{Pump();return Tree(w).OfType<T>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}static void Click(Window w,string n){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==n).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}
 static int Different(D.Bitmap a,D.Bitmap b){int count=0;for(int y=0;y<a.Height;y++)for(int x=0;x<a.Width;x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))count++;return count;}


 static void Toggle(Window w,string name,bool value){var check=Named<CheckBox>(w,name);check.IsChecked=value;check.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Pump();}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{
 var first=new ProcessCpuStamp{Id=1,Name="chrome",Start=100,Cpu=0};var next=new ProcessCpuStamp{Id=1,Name="chrome",Start=100,Cpu=TimeSpan.TicksPerSecond*2};Check(ProcessUsageLogic.CpuPercent(first,next,2,4)==25,"CPU percentage normalized across logical cores");next.Start=101;Check(!ProcessUsageLogic.CpuPercent(first,next,2,4).HasValue,"PID reuse cannot inherit previous CPU baseline");next.Start=100;Check(!ProcessUsageLogic.CpuPercent(first,next,Double.NaN,4).HasValue&&!ProcessUsageLogic.CpuPercent(first,next,20,4).HasValue,"invalid or stale CPU interval discarded");
 var stamps=new[]{new ProcessCpuStamp{Id=1,Name="chrome",Start=100,Cpu=20000000},new ProcessCpuStamp{Id=2,Name="Chrome",Start=100,Cpu=10000000},new ProcessCpuStamp{Id=3,Name="python",Start=100,Cpu=10000000}};var previous=stamps.ToDictionary(x=>x.Id,x=>new ProcessCpuStamp{Id=x.Id,Name=x.Name,Start=100,Cpu=0});var gpu=new[]{new ProcessGpuReading{Id=1,Engine="gpu0_3d",Value=20},new ProcessGpuReading{Id=2,Engine="gpu0_3d",Value=30},new ProcessGpuReading{Id=1,Engine="gpu0_copy",Value=15},new ProcessGpuReading{Id=3,Engine="gpu1_compute",Value=65}};var grouped=ProcessUsageLogic.Group(stamps,previous,1,4,gpu);Check(grouped.Length==2&&grouped.First(x=>x.Name=="chrome").Count==2,"same-name software processes grouped case-insensitively");Check(grouped.First(x=>x.Name=="chrome").Cpu==75&&grouped.First(x=>x.Name=="chrome").Gpu==50,"software CPU sums while GPU uses busiest aggregated engine");var snapshot=new ProcessUsageSnapshot{Utc=DateTime.UtcNow,Entries=grouped};var cpu=ProcessUsageLogic.Report(snapshot,"cpu",1,DateTime.UtcNow);var graphics=ProcessUsageLogic.Report(snapshot,"gpu",1,DateTime.UtcNow);Check(cpu.Contains("Google Chrome")&&!cpu.Contains("python.exe")&&graphics.Contains("python.exe")&&!graphics.Contains("Google Chrome"),"CPU and GPU independently select top K");Check(ProcessUsageLogic.Report(snapshot,"cpu",99,DateTime.UtcNow).Contains("Top 10"),"report clamps imported invalid top K");Check(ProcessUsageLogic.Report(snapshot,"cpu",3,DateTime.UtcNow.AddMinutes(1)).Contains("尚未就绪"),"stale ranking never masquerades as current");Check(ProcessUsageLogic.AlertText("CPU偏高","cpu@90",snapshot,2,DateTime.UtcNow).Contains("Google Chrome")&&ProcessUsageLogic.AlertText("温度高","cpuTemp",snapshot,2,DateTime.UtcNow)=="温度高","process attribution only appended to CPU GPU occupancy alerts");
 using(var sampler=new ProcessUsageSampler()){sampler.Poll(true);var timeout=DateTime.UtcNow.AddSeconds(10);while(sampler.Current==null&&DateTime.UtcNow<timeout){Pump();}Check(sampler.Current!=null,"native sampler publishes first Windows process snapshot");var initial=sampler.Current;timeout=DateTime.UtcNow.AddSeconds(12);while((sampler.Current==initial||sampler.Current==null||sampler.Current.Entries.All(x=>!x.Cpu.HasValue))&&DateTime.UtcNow<timeout){sampler.Poll(true);Pump();}var live=sampler.Current;Check(live!=null&&live.Entries.Any(x=>x.Cpu.HasValue),"native second sample returns real CPU deltas");Check(live!=null&&!String.IsNullOrWhiteSpace(live.GpuState),"native GPU path reports availability and source");File.WriteAllText(Path.Combine(args[0],"process-live-probe.json"),new JavaScriptSerializer().Serialize(new{native_cpu_entries=live==null?0:live.Entries.Count(x=>x.Cpu.HasValue),native_gpu_entries=live==null?0:live.Entries.Count(x=>x.Gpu.HasValue),gpu_state=live==null?"not ready":live.GpuState,process_names_saved=false}));Check(sampler.Poll(false)==null&&sampler.Current==null,"disabling ranking clears cached snapshot");}
 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;var voices=(VoiceRuntime)Get(pet,"voices");voices.Settings.Enabled=false;assistant.Config.Bubbles=true;pet.Show();Pump();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();var queue=(BubbleQueue)Get(pet,"messages");queue.Clear();Call(pet,"Say","测试待机气泡");Call(pet,"Tick",null,EventArgs.Empty);var bubble=(Window)Get(pet,"bubble");Check(bubble.IsVisible&&queue.Current!=null,"casual message shown before master disable");Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.Width=1220;w.Height=980;w.ShowPage("气泡外观");Toggle(w,"显示柯南对话气泡",false);Check(!assistant.Config.Bubbles&&!bubble.IsVisible&&queue.Current==null,"master switch immediately hides bubble and clears pending messages");Call(pet,"Say","不应出现");Call(pet,"NotifyUser","process-usage-report","不应显示的通知",3);Call(pet,"Tick",null,EventArgs.Empty);Check(!bubble.IsVisible&&queue.Current==null&&queue.Pending==0,"master blocks both casual and notification bubbles");Check(!voices.Settings.Enabled,"bubble switch leaves voice master untouched");Toggle(w,"显示柯南对话气泡",true);Call(pet,"Tick",null,EventArgs.Empty);Check(queue.Current==null&&!bubble.IsVisible,"reenabling does not replay suppressed bubbles");Call(pet,"Say","重新开启后的新消息");Call(pet,"Tick",null,EventArgs.Empty);Check(bubble.IsVisible&&queue.Current!=null,"new message appears after reenabling");Shot(w,Path.Combine(args[0],"bubble-master-switch.png"));
 w.ShowPage("侦探备忘录");Click(w,"资源预警");Named<TextBox>(w,"进程汇报 Top K").Text="5";Toggle(w,"资源预警时附上进程排行",false);Toggle(w,"采集软件 CPU / GPU 占用排行",false);Click(w,"让柯南汇报当前高占用软件");Check(assistant.Config.Monitor.ProcessReportCount==5&&!assistant.Config.Monitor.ProcessReportOnAlert&&!assistant.Config.Monitor.ProcessReportEnabled,"top K and independent reporting switches update configuration");Check(assistant.Notices.Items.Any(t=>t.Contains("进程排行采集已关闭")),"disabled manual report explains how to enable sampling");Shot(w,Path.Combine(args[0],"process-reporting-settings.png"));Toggle(w,"采集软件 CPU / GPU 占用排行",true);Toggle(w,"资源预警时附上进程排行",true);w.ShowPage("性能监控");Check(Tree(w).OfType<Button>().Any(x=>Convert.ToString(x.Content)=="汇报高占用软件"),"performance page exposes direct reporting action");var restored=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(restored.Config.Bubbles&&restored.Config.Monitor.ProcessReportCount==5&&restored.Config.Monitor.ProcessReportOnAlert,"bubble and top K preferences survive native runtime reload");restored.Telemetry.Dispose();
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"process527-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,isolated_settings=true,hardware_audio_tested=false}));return failures==0?0:1;}
